AssistantMessageToolRequest(name='create', tool_call_id='tooluse_bYEbBV2x6QH8mhAPAaUHtV', arguments={'file_text': "class ContactForm {
    constructor(formId) {
        this.form = document.getElementById(formId);
        this.fields = {
            fullName: document.getElementById('fullName'),
            email: document.getElementById('email'),
            phone: document.getElementById('phone')
        };
        this.errors = {
            fullName: document.getElementById('fullNameError'),
            email: document.getElementById('emailError'),
            phone: document.getElementById('phoneError')
        };
        this.successMessage = document.getElementById('successMessage');

        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        Object.keys(this.fields).forEach(key => {
            this.fields[key].addEventListener('blur', () => this.validateField(key));
            this.fields[key].addEventListener('input', () => this.clearError(key));
        });
    }

    validateField(fieldName) {
        let isValid = true;
        let errorMessage = '';

        if (fieldName === 'fullName') {
            isValid = this.validateFullName();
            if (!isValid) {
                errorMessage = this.fields.fullName.value.trim() === '' 
                    ? 'Full name is required.' 
                    : 'Full name must be at least 2 characters.';
            }
        } else if (fieldName === 'email') {
            isValid = this.validateEmail();
            if (!isValid) {
                errorMessage = this.fields.email.value.trim() === ''
                    ? 'Email address is required.'
                    : 'Please enter a valid email address.';
            }
        } else if (fieldName === 'phone') {
            isValid = this.validatePhone();
            if (!isValid) {
                errorMessage = 'Please enter a valid phone number format.';
            }
        }

        if (!isValid) {
            this.showError(fieldName, errorMessage);
        } else {
            this.clearError(fieldName);
        }

        return isValid;
    }

    validateFullName() {
        const value = this.fields.fullName.value.trim();
        return value.length >= 2;
    }

    validateEmail() {
        const value = this.fields.email.value.trim();
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return value.length > 0 && emailRegex.test(value);
    }

    validatePhone() {
        const value = this.fields.phone.value.trim();

        if (value === '') {
            return true;
        }

        const phoneRegex = /^[\d\s\-().+]*$/;
        if (!phoneRegex.test(value)) {
            return false;
        }

        const digitsOnly = value.replace(/\D/g, '');
        return digitsOnly.length >= 10 && digitsOnly.length <= 15;
    }

    showError(fieldName, message) {
        this.fields[fieldName].classList.add('error');
        this.fields[fieldName].classList.remove('success');
        this.errors[fieldName].textContent = message;
        this.errors[fieldName].classList.add('show');
    }

    clearError(fieldName) {
        this.fields[fieldName].classList.remove('error');
        this.errors[fieldName].textContent = '';
        this.errors[fieldName].classList.remove('show');
    }

    handleSubmit(e) {
        e.preventDefault();

        const isFullNameValid = this.validateField('fullName');
        const isEmailValid = this.validateField('email');
        const isPhoneValid = this.validateField('phone');

        if (isFullNameValid && isEmailValid && isPhoneValid) {
            this.submitForm();
        }
    }

    submitForm() {
        const formData = {
            fullName: this.fields.fullName.value.trim(),
            email: this.fields.email.value.trim(),
            phone: this.fields.phone.value.trim()
        };

        console.log('Form submitted with data:', formData);

        this.form.style.display = 'none';
        this.successMessage.style.display = 'block';

        setTimeout(() => {
            this.resetForm();
        }, 3000);
    }

    resetForm() {
        this.form.reset();
        this.form.style.display = 'block';
        this.successMessage.style.display = 'none';

        Object.keys(this.fields).forEach(key => {
            this.fields[key].classList.remove('error', 'success');
            this.errors[key].textContent = '';
            this.errors[key].classList.remove('show');
        });
    }
}

document.addEventListener('DOMContentLoaded', () => {
    new ContactForm('contactForm');
});
